const home = (path) => Object.values(GROUPS).map((g) => g[0]).find((p) => path.startsWith(p));

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil((async () => {
  for (const k of await caches.keys()) if (k.startsWith('vb-pb-') && k !== CACHE) await caches.delete(k);
  await self.clients.claim();
})()));

self.addEventListener('message', (e) => {
  if (!e.data || e.data.type !== 'cache') return;
  const urls = GROUPS[e.data.key] || [];
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const done = await Promise.allSettled(urls.map(async (u) => {
      if (await cache.match(u)) return;
      const res = await fetch(u, { cache: 'no-cache' });
      if (res.ok) await cache.put(u, res);
      else throw new Error(u);
    }));
    const port = e.ports && e.ports[0];
    if (port) port.postMessage({ ok: urls.length > 0 && done.every((d) => d.status === 'fulfilled') });
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  if (req.mode === 'navigate') {
    e.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      const net = fetch(req).then((res) => {
        if (res.ok) cache.put(url.pathname, res.clone());
        return res;
      }).catch(() => null);
      if (hit) {
        e.waitUntil(net);
        return hit;
      }
      const res = await net;
      if (res) return res;
      const fallback = home(url.pathname);
      return (fallback && (await cache.match(fallback))) || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    })());
    return;
  }
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (res.ok && res.type === 'basic') cache.put(req, res.clone());
    return res;
  })());
});
